    bo.dataset.giorno = k;
    const g = bo.querySelector(".bo-g"), dd = bo.querySelector(".bo-d");
    const corta = premiumVisto();
    if (g) g.textContent = d.toLocaleDateString("it-IT", { weekday: corta ? "short" : "long" }).replace(/\.$/, "");
