function lavoriAperti() { return Object.values(S.manutenzione).filter(m => m.stato !== "fatto").sort((a, b) => (urgenza(b) - urgenza(a)) || ((a.data || "") < (b.data || "") ? 1 : -1)); }   // 1.51.0: gli urgenti in cima
