  const minuti = lavori.reduce((s, p) => s + (Number(p.minuti) || 0), 0);
  return { camere: lavori.length, minuti, troppe: (m) => lavori.length > 0 && minuti > 0 && Math.round(Number(m) || 0) > minuti + Math.max(30, Math.round(minuti * 0.25)) };
