    const segmenti = unisciTurni([...(chiuso ? [{ inizio, fine, fonte: "app" }] : []), ...altri.filter(x => x.fine).map(x => ({ inizio: x.inizio, fine: x.fine, fonte: "app" })), ...pezzi]);
    const ap2 = altri.filter(x => !x.fine).pop() || null;
