function testoOreTurno(m) { m = Math.round(Number(m) || 0); const h = Math.floor(m / 60), r = m % 60; return h ? `${h} ${h === 1 ? "ora" : "ore"}${r ? ` e ${r} min` : ""}` : `${r} min`; }
