function arcobaleno(t) { let i = 0; return [...String(t || "")].map(ch => ch === " " ? " " : `<span class="ab${(i++ % 6) + 1}">${esc(ch)}</span>`).join(""); }
const OSPITI_MAT = { "🚪": "p-partenza", "🧳": "valigia" };
