      if (q) messe.add(q.id); for (const f of fs) messe.add(f.id);
      righe.push(tesseraGiro(q, rif, anteprima, q ? num.get(q.id) : 0, !!q && q.id === oraId, { camera: camera(p.camera), fondo: fs.map(f => ({ p: f, n: num.get(f.id), ora: f.id === oraId })) }));
