    if (id === "signore") { const tutte = signore().flatMap(z => pulizieDelGiorno(oggi, z.id)), f = tutte.filter(p => p.stato === "fatta").length; return tutte.length ? `oggi ${f} su ${tutte.length} pulizie` : "oggi niente pulizie"; }
