    if (id === "governante") { let s = ""; try { s = sottoGovernante(); } catch (e) {} return s || "le stelle e il catalogo"; }
    if (id === "sofia") { const d = domandeSofia(); return d ? `${d} ${d === 1 ? "cosa da guardare" : "cose da guardare"}` : "tutto chiaro"; }
