function svgStanza(id) {
  const W = 220, HH = 170;
  let pz;
  if (id === "signore") pz = { fa: (o) => isoLavanderia(o), s: 14.5, U: 6.5, V: 4.5, H: 5 };
  else if (id === "governante") pz = { fa: (o) => isoCamera(o, { soloLetti: true, singola: false }), s: 11.5, U: 9, V: 6, H: 5.2 };
  else pz = { fa: (o) => isoUfficio(o, id), s: 15, U: 7, V: 5, H: 4.2 };
  const larg = (pz.U + pz.V) * ISO_CX * pz.s, alto = pz.H * pz.s + (pz.U + pz.V) * ISO_SY * pz.s;
  const o = { x: (W - larg) / 2 + pz.V * ISO_CX * pz.s, y: (HH - alto) / 2 + pz.H * pz.s, s: pz.s };
  const r = pz.fa(o, {});
  return `<svg class="stanza-svg" viewBox="0 0 ${W} ${HH}" aria-hidden="true">${MATITA_DEFS.replace(/<\/?svg[^>]*>/g, "")}<g filter="url(#mtTrem)">${r.svg}</g></svg>`;
}
const stanzaTile = (st) => `<button type="button" class="stanza" data-vista="${st.vista}" data-stanza="${st.id}" aria-label="${esc(st.nome)}: ${esc(sottoStanza(st.id))}"><span class="stanza-fig"><img class="stanza-img" src="stanza-${st.id}.webp" alt="">${svgStanza(st.id)}</span><b>${esc(st.nome)}</b><span class="stanza-sotto">${esc(sottoStanza(st.id))}</span></button>`;
function vistaStanze() {
  const tile = stanzaTile;
  return `<section class="stanze" aria-label="Le stanze"><div class="stanze-griglia">${STANZE.map(tile).join("")}</div></section>`;
}
// le stanze stanno SOTTO Sofia e SOPRA la striscia dei giorni (fuori da #app, come la casa): una sezione sola, fatta una
// volta e aggiornata nelle righe (così i disegni di Gemini non si ricaricano a ogni disegno della pagina)
function disegnaStanze() {
  let s = document.getElementById("stanzeCasa");
  let vuoi = false; try { vuoi = !!(S.pronto && S.utente && S.utente.ruolo && proprietario() && !addetta() && S.vista === "oggi" && !(S.utente && S.utente.finta)); } catch (e) {}
  if (!vuoi) { if (s) s.remove(); document.body.classList.remove("ha-stanze"); return; }
  const header = document.querySelector("header"), app = document.getElementById("app");
  if (!s) {
    s = document.createElement("section"); s.id = "stanzeCasa"; s.className = "stanze"; s.setAttribute("aria-label", "Le stanze");
    s.innerHTML = `<div class="stanze-griglia">${STANZE.map(stanzaTile).join("")}</div>`;
    document.body.insertBefore(s, header || app);
  } else {
    for (const st of STANZE) { const b = s.querySelector(`.stanza[data-stanza="${st.id}"]`); if (!b) continue; const x = sottoStanza(st.id), r = b.querySelector(".stanza-sotto"); if (r && r.textContent !== x) { r.textContent = x; b.setAttribute("aria-label", `${st.nome}: ${x}`); } }
    const prima = header || app; if (prima && s.nextElementSibling !== prima) prima.parentNode.insertBefore(s, prima);   // sempre subito sopra la striscia dei giorni (sotto la casa)
  }
  document.body.classList.add("ha-stanze");
}
// l'immagine di Gemini c'è? la si mostra; se manca (404) resta il disegnino a matita (l'evento error non risale: si prende in cattura)
document.addEventListener("error", (e) => { const img = e.target; if (img && img.classList && img.classList.contains("stanza-img")) { img.remove(); } }, true);
// 1.44.0: LE FIGURE DEL LAVORO PER LE SIGNORE (lavoro-<blocco>.webp): Sofia vestita da addetta mostra il gesto di quel blocco
// (letto, bagno, camera, pavimenti, partenza, cucina; «biancheria» per il cambio completo del letto, «finale» prima di chiudere).
// Si vedono appena ci sono (evento load); se il file manca (404) la figura si toglie e resta solo la lista.
const FIGURE_LAVORO = { letto: "letto", bagno: "bagno", camera: "camera", pavimenti: "pavimenti", partenza: "partenza", cucina: "cucina", sopra: "letto" };
function figuraLavoro(blocco, totale, singolo) {
  let id = FIGURE_LAVORO[blocco] || ""; if (!id) return "";
  if (blocco === "letto" && totale) id = "biancheria";
  else if (blocco === "letto" && singolo && camereMatita()) id = "letto-singolo";   // 1.55.8: la camera singola: la signora rifà il letto singolo

  return `<img class="lavoro-img" src="lavoro-${id}${camereMatita() ? "-m" : ""}.webp" alt="" aria-hidden="true">`;   // 1.55.8: a matita
}
document.addEventListener("error", (e) => { const img = e.target; if (img && img.classList && img.classList.contains("lavoro-img")) { img.remove(); } }, true);
document.addEventListener("load", (e) => { const img = e.target; if (img && img.classList && img.classList.contains("lavoro-img")) { img.classList.add("pronta"); } }, true);
document.addEventListener("load", (e) => { const img = e.target; if (img && img.classList && img.classList.contains("stanza-img")) { const f = img.closest(".stanza-fig"); if (f) f.classList.add("con-foto"); } }, true);

// ============================================================================
//  1.49.0 SOFIA LA SEGRETARIA (Michele, 3/11 sera: «vorrei il microfono con Sofia segretaria, che la sua faccia mi esca a
//  fianco e mi parli, come nella prima pagina; una sintesi di quello che ha capito della giornata, anche a voce, ma veramente
//  una sintesi; il prospetto è un unico file che pubblica mio padre: non deve rinnovarlo ogni volta che parlo con lui nel
//  gruppo; ci devono essere più distinzioni tra i ruoli»).
//  - La segretaria ha un mestiere suo, distinto dalla governante: LE CHAT. Legge i messaggi di WhatsApp portati dal ponte
//    (il gruppo Albergo, papà, le signore, gli altri: la «posta», coi vocali già trascritti dal giro) e risponde su quelli:
//    «Com'è andata oggi?» → la SINTESI DELLA GIORNATA (4-7 frasi: chi ha scritto e di cosa, cosa è stato deciso, cosa c'è
//    domani, cosa resta in sospeso); le domande («che ha detto papà?», «dove hai messo le ore di Lucia?»); le CORREZIONI
//    («il nome in Aurora è Bianchi»): solo allora rilegge i messaggi dell'ultima lettura (con Argon, come prima) e riapre
//    la lettura da salvare. Le cose della casa (stelle, pulizie, paghe, messaggi alle signore) le rimanda alla governante,
//    con un tasto che apre la sua chat con la domanda già scritta.
//  - Costa zero sul credito: risposte e sintesi le fa il modello GRATUITO (il «sveglio», Flash, con la chiave normale; se
//    non risponde, lo svelto). Argon serve solo per la rilettura dopo una correzione.
//  - Il MICROFONO nella tendina (ascolta finché parli, si chiude da solo dopo 3 secondi di silenzio) e lei a fianco:
//    «Ti ascolto…» mentre parli, «…ci penso», e quando risponde PARLA (la voce di sempre) col filmato «parla» da segretaria
//    (segr-parla-3d.webm: finché non c'è resta quello fermo) e la pillola «⏹ Sofia» per farla smettere. La governante non
//    esce più in basso a destra mentre parla la segretaria, e la linguetta del microfono si nasconde a tendina aperta.
//  - La sintesi resta in importazioni/sintesi_<giorno> (la sera la fa anche il giro, da sola: sofia-giro) e si vede nella
//    tendina con «🔊 Leggimela». La chat con la segretaria sta in importazioni/segreteria-chat (ultime 40 righe, su tutti i telefoni).
//  - IL PROSPETTO NON PASSA PIÙ DALLE CHAT (scelta di Michele: «solo dal file Excel di papà»): nelle letture Sofia non propone
//    più soggiorni; se papà parla di camere lo mette in «note» («Prospetto: … — controlla il foglio»). Si riaccende in
//    Impostazioni → Sofia sempre accesa → «Prospetto anche dalle chat» (impostazioni/avvisi.prospettoChat).
//    1.53.0: l'interruttore non c'è più (le chat le legge sempre la segretaria; il prospetto solo dal foglio Excel).
// ============================================================================
const SGR_VELOCI = ["Com'è andata oggi?", "E ieri?", "Cosa c'è domani?"];
const MIC_SEGR_SVG = `<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2.1" stroke-linecap="round" aria-hidden="true"><rect x="9" y="3" width="6" height="11" rx="3"/><path d="M5 11a7 7 0 0 0 14 0"/><path d="M12 18v3"/></svg>`;
const ESITI_LETTURA = { salvata: "salvata nell'app", scartata: "messa da parte", vuota: "niente da cambiare", da_controllare: "ancora da controllare, non ho salvato niente", da_applicare: "la sto mettendo a posto nell'app", fatta: "messa a posto nell'app", sostituita: "riletta più tardi" };   // 1.51.0
// 1.51.0: le cose di una lettura del modo nuovo, in parole: fatte (non annullate), da confermare, le domande
function vociFatte(x) {
  const via = (t) => String(t || "").replace(/^\S+\s/, "").replace(/\s+/g, " ").trim();
  return [...(Array.isArray(x.fatti) ? x.fatti : []).filter(f => !f.annullato && f.tipo !== "te").map(f => "Fatto: " + via(f.testo)),
    ...(Array.isArray(x.proposte) ? x.proposte : []).filter(p => !p.esito).map(p => "Da confermare: " + via(p.testo)),
    ...(Array.isArray(x.domande) ? x.domande : []).filter(d => !d.risposta).map(d => "Domanda: " + d.domanda)].slice(0, 12);
}
// 1.53.0 (Michele: «se la segreteria fa bene il suo dovere, le cose delle chat da controllare non servono più»): l'interruttore
// «Prospetto anche dalle chat» non c'è più e il valore vecchio in avvisi non conta: le chat di WhatsApp le legge e le mette a
// posto sempre la segretaria (modo nuovo), il prospetto arriva solo dal foglio Excel di papà
function prospettoDalleChat() { return false; }
