// 0.84 - UNA PORTA SOLA: l'ultimo scambio con lei sta qui, sotto il filmato, coi tasti "Sì, fallo / No"
// a portata di pollice. Prima la proposta finiva nella pagina della chat e dalla casa non si vedeva.
function ultimoScambio() {
  const conv = conversazione();
  const n = conv.length;
  const ultimo = n ? conv[n - 1] : null;
  const pezzi = [];
  const corto = (t, max) => { t = String(t || "").trim(); return t.length > max ? t.slice(0, max - 1).trimEnd() + "…" : t; };
  // l'ultima cosa che ha detto Michele (se è l'ultimo messaggio, lei sta ancora pensando)
  const mio = [...conv].reverse().find(m => m.chi === "io");
  const lei = [...conv].reverse().find(m => m.chi === "gov");
  const iMio = mio ? conv.lastIndexOf(mio) : -1, iLei = lei ? conv.lastIndexOf(lei) : -1;
  if (!ultimo) return { html: "", tasti: false, pensa: false, lei: null, mio: null };
  if (mio && iMio > iLei - 2) pezzi.push(`<div class="cc-io">${esc(corto(mio.testo, 160))}</div>`);
  if (govScrive || (ultimo && ultimo.chi === "io")) pezzi.push(`<div class="cc-lei cc-pensa">${esc(nomeGov())} ci pensa…</div>`);
  else if (lei && iLei >= iMio) {
    const tasti = tastiAttivi(lei).length ? tastiAttivi(lei) : null;
    pezzi.push(`<div class="cc-lei">${esc(String(lei.testo || "").trim()).replace(/\n/g, "<br>")}</div>`);
    if (tasti) pezzi.push(`<div class="cc-tasti">${tasti.slice(0, 6).map(t => `<button type="button" class="${t.k === "si" ? "cc-si" : t.k === "no" ? "cc-no" : ""}" data-casa-tasto="${esc(String(iLei))}|${esc(String(t.k))}">${esc(t.testo)}</button>`).join("")}</div>`);
    else if (lei.scelto) pezzi.push(`<div class="cc-scelto">${esc(lei.scelto)}</div>`);
  }
  const pensa = !!(govScrive || (ultimo && ultimo.chi === "io"));
  const risposta = !pensa && lei && iLei >= iMio ? lei : null;
  return { html: pezzi.join(""), tasti: !!(risposta && Array.isArray(risposta.tasti) && risposta.tasti.length), pensa, lei: risposta, mio: mio || null };
}
// 1.1.0: nello stile Premium la chat della casa e' la conversazione vera (come nella scheda di Sofia), non solo
// l'ultimo scambio: fumetti pieni, leggibili sopra Sofia velata
function bolleCasa(max = 40) {
  const conv = conversazione();
  const ultimi = conv.slice(-max), base = conv.length - ultimi.length;
  let iLei = -1; for (let i = conv.length - 1; i >= 0; i--) { if (conv[i].chi === "gov") { iLei = i; break; } }
  const pensa = govScrive || (conv.length && conv[conv.length - 1].chi === "io");
  const bolle = ultimi.map((m, j) => {
    const i = base + j;
    const testo = esc(String(m.testo || "").trim()).replace(/\n/g, "<br>");
    if (m.chi === "io") return `<div class="sv-riga sv-io"><div class="cc-io">${testo}</div></div>`;
    const tasti = (i === iLei && !pensa && tastiAttivi(m).length)
      ? `<div class="cc-tasti">${tastiAttivi(m).slice(0, 6).map(x => `<button type="button" class="${x.k === "si" ? "cc-si" : x.k === "no" ? "cc-no" : ""}" data-casa-tasto="${esc(String(i))}|${esc(String(x.k))}">${esc(x.testo)}</button>`).join("")}</div>`
      : (m.scelto ? `<div class="cc-scelto">${esc(m.scelto)}</div>` : "");
    return `<div class="sv-riga sv-lei"><span class="sv-foto" aria-hidden="true"></span><div class="sv-colonna"><div class="cc-lei">${testo}</div>${tasti}</div></div>`;
  }).join("");
  const attesa = pensa ? `<div class="sv-riga sv-lei"><span class="sv-foto" aria-hidden="true"></span><div class="sv-colonna"><div class="cc-lei cc-pensa">${esc(nomeGov())} ci pensa…</div></div></div>` : "";
  const vuota = `<div class="sv-riga sv-lei"><span class="sv-foto" aria-hidden="true"></span><div class="sv-colonna"><div class="cc-lei">Dimmi pure, ${esc(nomeMio())}: scrivimi qui sotto o tocca il microfono e parlami.</div></div></div>`;
  return (bolle || vuota) + attesa;
}
