  const cuscini = tipo === "doppio" ? cuscino(x + 2.4) + cuscino(x + 14.2) : tipo === "uso" ? cuscino(x + 2.4) + `<rect x="${x + 14.2}" y="3.4" width="9.4" height="5.6" rx="2" fill="none" stroke="#B8AE9F" stroke-width="1" stroke-dasharray="2 1.6"/>` : cuscino(x + 2.8);
