const RX_PULIZIE_FATTE = /\b(?:hanno (?:fatto|finito|pulito)|ha (?:fatto|finito|pulito)|sono (?:state )?(?:fatte|finite|pulite)|e (?:stata )?(?:fatta|finita|pulita)|tutte fatte|tutto fatto|gia fatt[ae]|segna\w* (?:come )?fatt[ae])\b/;
