    const cand = [...proposteGov(lun).proposte, ...proposteGov(L.aggiungiGiorni(lun, 7)).proposte].filter(c => c.luogo === dd.camera && !c.grande && !S.pulizie[idPuliziaGov(c)]);
    const miei = cand.filter(c => c.data >= dd.da && c.data < dd.fino);
