    if (k === "parole") { await notaDellaGovernante(L.oggiISO(), null, `Paghe ${L.etichettaSettimana(dd.chiusa)}: ${parole}`, true); return { fatto: `segnato nelle note: «${parole}». Le paghe restano da confermare in Paghe.` }; }
    const fatte = [];
