    const chi = k === "papa" ? "papà" : k === "parole" ? parole : (S.utente.nome || "Michele");
    const voci = { ...((S.spesa && S.spesa.voci) || {}) }; const id = `${L.oggiISO()}_${L.normNome(dd.prodotto).replace(/ /g, "-")}_${dd.zona}`;
