    if (k === "alzo") { const nuovo = Math.ceil((dd.speso + 50) / 10) * 10; await salvaGov({ soglie: { ...soglieGov(), budgetStelle: nuovo } }); return { fatto: `budget del mese alzato a ${eur(nuovo)} (in Regole → Due soglie piccole lo cambi quando vuoi).` }; }
