// --- il giro ---
function doveDaTipo(tipo, luogo) { return tipo === "camera" ? "stanza" : tipo === "bagno" ? "bagno" : tipo === "cucina" ? "cucina" : tipo === "balcone" ? "balcone" : tipo === "corridoio" ? ["corridoio_p1", "corridoio_p2"] : (luogo?.id || tipo); }
