  const superficiExtra = { ...((S.gov && S.gov.superficiExtra) || {}) }; superficiExtra[x.tipo] = [...(superficiExtra[x.tipo] || []), { id: sid, nome: cosa, oggetto: x.oggetto, luogo: g.luogo, data: L.oggiISO() }];
