const AL_GRUPPI = [["cognome"], ["nome"], ["sesso"], ["nascita"], ["comuneNascita", "comuneNome", "provNascita", "statoNascita", "statoNome", "natoInItalia"], ["cittadinanza", "cittNome"], ["tipoDoc"], ["numDoc"], ["luogoRilascio", "rilascioNome"]];
