  try { const [cod, letto] = await Promise.all([alCodici(), DOC.leggiFoto(file, (s, p) => alAttesa(`${AL_FASI[s] || "Leggo il documento…"}${s === "recognizing text" && p ? " " + Math.round(p * 100) + "%" : ""}`))]); ris = alDaLettura(letto, cod); } catch (e) {}
