  return `<button type="button" class="fa-c mg mg${st}${largo ? " mg-largo" : ""}" data-man-posto="${esc(posto || "_")}" aria-label="${esc(aria)}"><b class="fa-nome">${esc(nome)}</b>${MG_ICONE[st]}${parola ? `<b class="mg-parola">${parola}</b>` : ""}${cosa}${banda}</button>`;
