  if (files.some(f => /^audio\//.test(tipo(f)) || /\.(opus|ogg|m4a|mp3|aac|wav)$/.test(nome(f)))) { await apriChatWA(files); return; }
  const foto = files.find(f => /^image\//.test(tipo(f)) || /\.(jpe?g|png|webp|heic)$/.test(nome(f)));
