    console.warn("lettura sofia", e);
    d.ia = { errore: String((e && e.message) || e).slice(0, 200), n: messaggi.length };
    if (Array.isArray(d.postaIds) && d.postaIds.length) liberaLettura("errore: " + d.ia.errore);   // 1.18.0
