  const sq = squadra(); const nuovo = { ...(S.squadra || {}) }; nuovo[zona] = { ...(sq[zona] || {}), ...patch };
  S.squadra = nuovo; disegna();
  try { await S.db.salva("impostazioni", "squadra", { ...nuovo, aggiornato: S.db.adesso() }, false); pianifica(); }
